-- Where people leave from for games, and how they usually go. Asked in the introduction (after creating an account)
-- and in the profile, always optional.
--
-- - `municipality`: the 308 concelhos, public reference data. INE codes (DTMN), names and districts from CAOP via
--   geoapi.pt; the point is each concelho's centroid (Funchal's falls at sea because of the Selvagens, so it is the
--   city centre). Açores and Madeira take the place of the district.
-- - `profile_home`: the concelho and the usual way of going, one row per person. Only its owner reads or writes it.
--   It is never shown to anyone else: the app uses it to put first the rides that leave close by.

create table public.municipality (
  id text primary key check (id ~ '^[0-9]{4}$'),
  name text not null check (char_length(name) between 2 and 60),
  district text not null check (char_length(district) between 2 and 40),
  region text not null check (region in ('mainland', 'madeira', 'azores')),
  location extensions.geography(point, 4326) not null,
  latitude double precision
    generated always as (extensions.st_y(location::extensions.geometry)) stored,
  longitude double precision
    generated always as (extensions.st_x(location::extensions.geometry)) stored,
  created_at timestamptz not null default now()
);

create index municipality_district_idx on public.municipality (district);

create table public.profile_home (
  profile_id uuid primary key references public.profile (id) on delete cascade,
  municipality_id text references public.municipality (id),
  usual_transport text check (usual_transport in ('driver', 'passenger', 'public_transport')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index profile_home_municipality_idx on public.profile_home (municipality_id);

create trigger profile_home_set_updated_at
  before update on public.profile_home
  for each row execute function public.set_updated_at();

-- Row level security.
alter table public.municipality enable row level security;
alter table public.profile_home enable row level security;

create policy "municipalities are readable by everyone"
  on public.municipality for select to anon, authenticated using (true);

create policy "users read their own home"
  on public.profile_home for select to authenticated
  using ((select auth.uid()) = profile_id);
create policy "users add their own home"
  on public.profile_home for insert to authenticated
  with check ((select auth.uid()) = profile_id);
create policy "users change their own home"
  on public.profile_home for update to authenticated
  using ((select auth.uid()) = profile_id)
  with check ((select auth.uid()) = profile_id);
create policy "users remove their own home"
  on public.profile_home for delete to authenticated
  using ((select auth.uid()) = profile_id);

revoke all on public.municipality, public.profile_home from anon, authenticated;
grant select on public.municipality to anon, authenticated;
grant select, insert, update, delete on public.profile_home to authenticated;

